import java.util.*;

public class Main {
    static final class Record {
        final String key;
        final String value;
        final long offset;
        Record(String key, String value, long offset) {
            this.key = key;
            this.value = value;
            this.offset = offset;
        }
    }

    static final class Partition {
        final int id;
        final int replicationFactor;
        int inSyncReplicas;
        final List<Record> log = new ArrayList<>();
        Partition(int id, int replicationFactor) {
            this.id = id;
            this.replicationFactor = replicationFactor;
            this.inSyncReplicas = replicationFactor;
        }
        long append(String key, String value, boolean acksAll, int minInSyncReplicas) {
            if (acksAll && inSyncReplicas < minInSyncReplicas) {
                throw new IllegalStateException("NotEnoughReplicas for partition " + id);
            }
            long offset = log.size();
            log.add(new Record(key, value, offset));
            return offset;
        }
    }

    static final class Topic {
        final List<Partition> partitions;
        Topic(int partitionCount, int replicationFactor) {
            partitions = new ArrayList<>();
            for (int i = 0; i < partitionCount; i++) partitions.add(new Partition(i, replicationFactor));
        }
        int partitionFor(String key) {
            return Math.floorMod(key.hashCode(), partitions.size());
        }
        long send(String key, String value, boolean acksAll, int minInSyncReplicas) {
            return partitions.get(partitionFor(key)).append(key, value, acksAll, minInSyncReplicas);
        }
    }

    static final class ConsumerGroup {
        static Map<String, List<Integer>> assign(int partitionCount, List<String> members) {
            Map<String, List<Integer>> result = new LinkedHashMap<>();
            for (String member : members) result.put(member, new ArrayList<>());
            for (int p = 0; p < partitionCount; p++) {
                result.get(members.get(p % members.size())).add(p);
            }
            return result;
        }
    }

    static final class OffsetStore {
        final Map<Integer, Long> committed = new HashMap<>();
        long committedOffset(int partition) { return committed.getOrDefault(partition, 0L); }
        void commit(int partition, long nextOffset) { committed.put(partition, nextOffset); }
    }

    public static void main(String[] args) {
        Topic topic = new Topic(3, 3);
        String key = "order-42";
        int partition = topic.partitionFor(key);
        long firstOffset = topic.send(key, "created", true, 2);
        long secondOffset = topic.send(key, "paid", true, 2);
        assert topic.partitionFor(key) == partition : "same key must route to same partition";
        assert firstOffset == 0 && secondOffset == 1 : "offset within partition is monotonically increasing";

        boolean rejected = false;
        Partition unhealthy = topic.partitions.get(1);
        unhealthy.inSyncReplicas = 1;
        try {
            unhealthy.append("order-9", "created", true, 2);
        } catch (IllegalStateException ex) {
            rejected = ex.getMessage().contains("NotEnoughReplicas");
        }
        assert rejected : "acks=all with ISR below minISR must reject";

        List<String> members = List.of("c1", "c2", "c3", "c4", "c5");
        Map<String, List<Integer>> assignment = ConsumerGroup.assign(3, members);
        long idleConsumers = assignment.values().stream().filter(List::isEmpty).count();
        assert idleConsumers == 2 : "consumers beyond partition count are idle";

        OffsetStore offsets = new OffsetStore();
        Record delivery = topic.partitions.get(partition).log.get(0);
        boolean redeliveredAfterCrash = offsets.committedOffset(partition) == delivery.offset;
        offsets.commit(partition, delivery.offset + 1);
        assert redeliveredAfterCrash : "before commit, crash causes redelivery (at-least-once)";
        assert offsets.committedOffset(partition) == 1;

        System.out.println("keyPartition=" + partition + ", offsets=" + firstOffset + "/" + secondOffset);
        System.out.println("acksAllRejected=" + rejected + ", idleConsumers=" + idleConsumers);
        System.out.println("redeliveredBeforeCommit=" + redeliveredAfterCrash + ", committedOffset=" + offsets.committedOffset(partition));
    }
}
